mapper.update:
UPDATE AI_WORKFLOW_EXECUTION
   SET STATUS = #{status}
     , CURRENT_STEP_INDEX = #{currentStepIndex}
     , CONTEXT_JSON = CAST(#{contextJson} AS jsonb)
     , RESULT_TEXT = #{resultText}
     , ERROR_MESSAGE = #{errorMessage}
     , UPDATED_AT = #{updatedAt, jdbcType=TIMESTAMP}

     , PAUSE_REQUESTED = CASE WHEN #{status} = 'RUNNING' THEN PAUSE_REQUESTED ELSE FALSE END
 WHERE EXECUTION_ID = #{executionId}

mapper.delete:
DELETE FROM AI_WORKFLOW_EXECUTION
 WHERE EXECUTION_ID = #{executionId}
   AND STATUS = 'QUEUED'

mapper.update:
UPDATE AI_WORKFLOW_EXECUTION
   SET STATUS = 'RUNNING'
     , OWNER_INSTANCE = #{ownerInstance}
     , HEARTBEAT_AT = now()
     , UPDATED_AT = #{updatedAt, jdbcType=TIMESTAMP}
 WHERE EXECUTION_ID = #{executionId}
   AND STATUS = 'QUEUED'

UPDATE AI_WORKFLOW_EXECUTION
   SET STATUS = 'PAUSED'
     , PAUSE_REQUESTED = FALSE
     , UPDATED_AT = #{updatedAt, jdbcType=TIMESTAMP}
 WHERE EXECUTION_ID = #{executionId}
   AND STATUS = 'QUEUED'

mapper.select:
SELECT PAUSE_REQUESTED
  FROM AI_WORKFLOW_EXECUTION
 WHERE EXECUTION_ID = #{executionId}

mapper.update:
UPDATE AI_WORKFLOW_EXECUTION
   SET STATUS = 'QUEUED'
     , CURRENT_STEP_INDEX = #{currentStepIndex}
     , ERROR_MESSAGE = NULL
     , PAUSE_REQUESTED = FALSE
     , OWNER_INSTANCE = #{ownerInstance}
     , HEARTBEAT_AT = now()
     , UPDATED_AT = #{updatedAt, jdbcType=TIMESTAMP}
 WHERE EXECUTION_ID = #{executionId}
   AND STATUS = #{fromStatus}

mapper.select:
SELECT 
  FROM AI_WORKFLOW_EXECUTION
 WHERE 1 = 1
AND STATUS = #{status}
AND WORKFLOW_ID = #{workflowId}
AND CALLER = #{caller}
 ORDER BY CREATED_AT DESC
 LIMIT #{size} OFFSET #{offset}

mapper.sql:
 WHERE 1 = 1
AND STATUS = #{status}
AND POSITION(LOWER(#{workflowId}) IN LOWER(WORKFLOW_ID)) > 0
AND POSITION(LOWER(#{executionId}) IN LOWER(EXECUTION_ID)) > 0
AND CALLER = #{caller}
AND REQUESTED_BY = #{requestedBy}
